// The -O peephole pass: applies the superoptimizer's proved rewrite rules
// (src/rules.js, generated by superopt/search.js) and folds constants in
// straight-line runs of pure i32 code.
//
// A rule's left side is a pattern: `local.get xN` binds a local (which must
// be one of the function's odd locals if the rule assumed so), and a
// symbolic constant `kconst K` binds any i32.const. Every rule strictly
// shortens the code, and so does folding, so rewriting a run terminates.

export const PURE_OPS = new Set([
  'i32.const', 'local.get', 'i32.add', 'i32.sub', 'i32.mul', 'i32.and', 'i32.or', 'i32.xor',
  'i32.shl', 'i32.shr_s', 'i32.shr_u', 'i32.eq', 'i32.ne', 'i32.lt_s', 'i32.lt_u', 'i32.gt_s', 'i32.gt_u',
  'i32.le_s', 'i32.le_u', 'i32.ge_s', 'i32.ge_u', 'i32.eqz', 'select',
]);

export function foldBinary(op, a, b) {
  switch (op) {
    case 'i32.add': return (a + b) | 0;
    case 'i32.sub': return (a - b) | 0;
    case 'i32.mul': return Math.imul(a, b);
    case 'i32.and': return a & b;
    case 'i32.or': return a | b;
    case 'i32.xor': return a ^ b;
    case 'i32.shl': return a << (b & 31);
    case 'i32.shr_s': return a >> (b & 31);
    case 'i32.shr_u': return (a >>> (b & 31)) | 0;
    case 'i32.eq': return +(a === b);
    case 'i32.ne': return +(a !== b);
    case 'i32.lt_s': return +(a < b);
    case 'i32.gt_s': return +(a > b);
    case 'i32.le_s': return +(a <= b);
    case 'i32.ge_s': return +(a >= b);
    case 'i32.lt_u': return +((a >>> 0) < (b >>> 0));
    case 'i32.gt_u': return +((a >>> 0) > (b >>> 0));
    case 'i32.le_u': return +((a >>> 0) <= (b >>> 0));
    case 'i32.ge_u': return +((a >>> 0) >= (b >>> 0));
    default: return undefined;
  }
}

const isConst = (ins) => ins !== undefined && ins[0] === 'i32.const';

// Constant folding at `pos`: returns [length replaced, replacement] or null.
function foldAt(code, pos) {
  const [a, b, c] = [code[pos], code[pos + 1], code[pos + 2]];
  if (!isConst(a)) return null;
  if (b && b[0] === 'i32.eqz') return [2, ['i32.const', +((a[1] | 0) === 0)]];
  if (!isConst(b) || !c) return null;
  const v = foldBinary(c[0], a[1] | 0, b[1] | 0);
  return v === undefined ? null : [3, ['i32.const', v]];
}

// The value of a constant placeholder given the symbols' values.
export function kValue(kvals, { k, f, d }) {
  const kval = kvals[k];
  switch (f) {
    case 'id': return kval | 0;
    case 'sum': return (kval + kvals[d]) | 0;
    case 'diff': return (kval - kvals[d]) | 0;
    case 'add': return (kval + d) | 0;
    case 'neg': return (-kval) | 0;
    case 'shl1': return (kval << 1) | 0;
    case 'shr1': return kval >> 1;
    default: throw new Error(`kValue: ${f}`);
  }
}

export function indexRules(rules) {
  const byFirst = new Map();
  const keyOf = ([op, arg]) => (op === 'kconst' ? 'i32.const' : op === 'i32.const' ? `i32.const ${arg}` : op);
  for (const rule of rules) {
    const k = keyOf(rule.lhs[0]);
    if (!byFirst.has(k)) byFirst.set(k, []);
    byFirst.get(k).push(rule);
  }
  for (const list of byFirst.values()) list.sort((a, b) => b.lhs.length - a.lhs.length);
  return { byFirst, rules };
}

// Rules that may match at an instruction, longest first.
function candidates(index, ins) {
  if (ins[0] !== 'i32.const') return index.byFirst.get(ins[0]) ?? [];
  const key = `=${ins[1] | 0}`;
  let list = index.byFirst.get(key);
  if (!list) {
    list = [...(index.byFirst.get(`i32.const ${ins[1] | 0}`) ?? []), ...(index.byFirst.get('i32.const') ?? [])];
    list.sort((a, b) => b.lhs.length - a.lhs.length);
    index.byFirst.set(key, list);
  }
  return list;
}

export function matchAt(code, pos, rule, isOdd) {
  if (pos + rule.lhs.length > code.length) return null;
  const vars = {}, ks = {};
  for (let i = 0; i < rule.lhs.length; i++) {
    const [pop, parg] = rule.lhs[i];
    const [op, arg] = code[pos + i];
    if (pop === 'kconst') {
      if (op !== 'i32.const') return null;
      if (parg.k in ks && ks[parg.k] !== (arg | 0)) return null;
      ks[parg.k] = arg | 0;
      continue;
    }
    if (pop !== op) return null;
    if (op === 'i32.const' && (arg | 0) !== (parg | 0)) return null;
    if (op === 'local.get') {
      if (parg in vars) { if (vars[parg] !== arg) return null; continue; }
      if (rule.odd[+parg.slice(1)] && !isOdd(arg)) return null;
      vars[parg] = arg;
    }
  }
  return rule.rhs.map(([op, arg]) => {
    if (op === 'kconst') return ['i32.const', kValue(ks, arg)];
    if (op === 'local.get') return ['local.get', vars[arg]];
    return arg === undefined ? [op] : [op, arg];
  });
}

// Rewrites one run of pure instructions to a fixed point. `stats` counts uses per rule.
export function rewriteRun(code, index, isOdd, stats) {
  let out = code.slice();
  let pos = 0;
  while (pos < out.length) {
    let applied = false;
    const folded = foldAt(out, pos);
    if (folded) {
      out.splice(pos, folded[0], folded[1]);
      if (stats) stats.set('fold', (stats.get('fold') ?? 0) + 1);
      pos = Math.max(0, pos - 8);
      continue;
    }
    for (const rule of candidates(index, out[pos])) {
      const rhs = matchAt(out, pos, rule, isOdd);
      if (!rhs) continue;
      out.splice(pos, rule.lhs.length, ...rhs);
      if (stats) stats.set(rule.id, (stats.get(rule.id) ?? 0) + 1);
      pos = Math.max(0, pos - 8); // a rewrite can enable a match that starts a little earlier
      applied = true;
      break;
    }
    if (!applied) pos++;
  }
  return out;
}

// Rewrites a whole function body (with structured control flow) in place.
export function rewriteBody(body, index, oddLocals, stats) {
  const odd = new Set(oddLocals);
  const isOdd = (name) => odd.has(name);
  const out = [];
  let i = 0;
  while (i < body.length) {
    if (!PURE_OPS.has(body[i][0])) { out.push(body[i++]); continue; }
    let j = i;
    while (j < body.length && PURE_OPS.has(body[j][0])) j++;
    out.push(...rewriteRun(body.slice(i, j), index, isOdd, stats));
    i = j;
  }
  return out;
}

// Applies the rules to every compiler-generated function of a module (the
// hand-written runtime has no odd-local metadata and is left untouched).
export function optimizeModule(mod, rules, stats = new Map()) {
  const index = indexRules(rules);
  let before = 0, after = 0;
  for (const f of mod.funcs) {
    if (!f.oddLocals) continue;
    before += f.body.length;
    f.body = rewriteBody(f.body, index, f.oddLocals, stats);
    after += f.body.length;
  }
  return { before, after, stats };
}
